"aef-vignettaz":{"rev":"701094c0f29830973ed451af10cf2e10e7250a50fb10b626c80cc0fb506d8715","strings":{"name":"Café parents-enfants · Vignettaz","age":"Alter noch nicht bestätigt","schedule":"7. Oktober 15:00–17:00; 7. November 09:00–11:00","price":"Preis nicht veröffentlicht","address":"École primaire de la Vignettaz, Route de la Gruyère 9, 1700 Fribourg","notes[0]":"Die Erwachsenen sprechen über Erziehung und die Begleitung von Kindern. Die Kinder nehmen am gemeinsamen Treffen teil.","notes[1]":"Altersgrenze, Kosten, Anmeldepflicht und Sprache der Gastgeberin oder des Gastgebers sind nicht angegeben.","notes[2]":"Die Zeiten der Treffen unterscheiden sich: Mittwochnachmittag und Samstagvormittag. Prüfen Sie den Eingang zu Gebäude C vor der Anreise.","practical.indoor.text":"Das Treffen findet im Mehrzwecksaal von Gebäude C der Primarschule statt.","research.findings[0].field":"Datum und Ort","research.findings[0].text":"AEF veröffentlicht ein Treffen am 7. Oktober 2026, 15:00–17:00, im Mehrzwecksaal von Gebäude C der Schule Vignettaz, Route de la Gruyère 9.","research.findings[1].field":"Zweites Datum","research.findings[1].text":"Das nächste Treffen im selben Saal am 7. November 2026 findet am Vormittag statt, 09:00–11:00.","research.remaining[0]":"Prüfen Sie Alter, Kosten, Anmeldung, Sprache und den Eingang zu Gebäude C.","contacts[0].name":"Éducation Familiale: FR 026 321 48 70; DE 026 322 86 33","sources[0].label":"AEF-Kalender: beide Daten","sources[1].label":"AEF: Treffen in der Vignettaz","sources[2].label":"Zweites Datum"}},
"aef-villars":{"rev":"95742b7dbcd1ab80bca8317a22ddc50c2974168fd3566620e880d752b81f1415","strings":{"name":"Café parents-enfants · Villars-Vert","age":"Das Alter für das Freitagscafé ist nicht angegeben","schedule":"Fr 09:00–11:00 · veröffentlichte Termine bis 18.12.2026","price":"Preis nicht veröffentlicht","address":"Route de Villars-Vert 26, 1752 Villars-sur-Glâne","notes[0]":"Ein Spieltreff für ein Kind mit einer erwachsenen Person und ein Gespräch zwischen Eltern und einer Person aus dem Personal von Éducation Familiale.","notes[1]":"Preis, Anmeldung, Sprache und allfällige separate Altersgrenzen für den Freitagstreff sind im aktuellen Programm nicht angegeben. Nicht zu verwechseln mit der separaten kostenlosen Tilou-Gruppe am Montag in denselben Räumen.","notes[2]":"Hier sind nur die von der AEF veröffentlichten Daten aufgeführt, ohne Schulferien.","practical.indoor.text":"Der Treff findet drinnen im Le Milieu statt.","research.findings[0].field":"Veröffentlichte Treffs","research.findings[0].text":"Der AEF-Kalender führt Treffs am Freitag von 09:00 bis 11:00 im Le Milieu bis 18. Dezember 2026 auf. Im Oktober gibt es eine Pause.","research.findings[1].field":"Ort und Format","research.findings[1].text":"Die Gemeinde beschreibt das Freitagscafé der AEF als Kinder, die mit erwachsenen Personen spielen, und ein Gespräch mit einer Person aus dem Personal von Éducation Familiale an der Route de Villars-Vert 26.","research.remaining[0]":"Für das Freitagscafé müssen Altersgrenzen, Kosten, Anmeldung und Sprache separat geklärt werden; die Bedingungen der Tilou-Gruppe am Montag gelten nicht unbedingt.","contacts[0].name":"Éducation Familiale: FR 026 321 48 70; DE 026 322 86 33","sources[0].label":"AEF: Herbsttreffs und Adresse","sources[1].label":"Gemeinde: Format mit Elternteil und Adresse"}},
"aerodrome-epagny-play":{"rev":"d59f24c85d49f4fe3ea60beae34208ad9e79507f692f48875974eaef6707c968","strings":{"name":"Flugplatzrestaurant · Spielbereich","intro":"Ein Restaurant beim Flugplatz mit grossem Spielbereich und einer Terrasse.","age":"Altersgrenzen sind nicht veröffentlicht.","schedule":"Mi–Do 09:00–22:00; Fr 09:00–23:00; Sa–So 08:30–23:00","price":"Der Preis ist nicht veröffentlicht.","address":"Route de l’Aérodrome 40, 1663 Epagny","notes[0]":"Sie können den Flugplatz beobachten, aber die Seite verspricht weder Flugbetrieb noch die Sicherheit des Beobachtungsbereichs.","notes[1]":"Die Öffnungszeiten des Restaurants sind für 2026 veröffentlicht. Der Spielbereich kann bei einem privaten Anlass nicht verfügbar sein.","practical.indoor.text":"Das Flugplatzrestaurant nennt einen grossen Spielbereich und eine Terrasse.","practical.warnings[0]":"Das Alter der Geräte, die Preise und die Verfügbarkeit des Spielbereichs ohne Bestellung sind nicht beschrieben.","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Das Flugplatzrestaurant nennt einen grossen Spielbereich und eine Terrasse.","research.remaining[0]":"Das Alter der Geräte, die Preise und die Verfügbarkeit des Spielbereichs ohne Bestellung sind nicht beschrieben.","contacts[0].name":"Café-Restaurant de l’Aérodrome","sources[0].label":"Grosser Spielbereich, Terrasse und Öffnungszeiten"}},
