"biblio-marly":{"rev":"ed9358b0b117d0cfb598fdb6f10c94476694ea5f050ebd1c0a6361c5b1a986cd","strings":{"name":"Bibliothèque régionale de Marly","age":"Familienbesuch","schedule":"Di, Mi, Fr 14:00–18:00 · Do, Sa 09:00–12:00; Termin möglich, noch nicht bestätigt","price":"Preis nicht veröffentlicht","address":"Route de Fribourg 15, Marly","notes[0]":"Die Sprache der gastgebenden Person oder des Angebots ist nicht bestätigt.","notes[1]":"Die Öffnungszeiten der Bibliothek sind nicht dieselben wie die Zeiten von Né pour lire.","research.findings[0].field":"Zeiten und Besuche","research.findings[0].text":"Das kantonale Verzeichnis nennt Di, Mi, Fr 14:00–18:00 und Do, Sa 09:00–12:00 unter der Bezeichnung «Sur rendez-vous». Es ist noch zu prüfen, ob für einen gewöhnlichen Besuch ein Termin nötig ist.","research.remaining[0]":"Ob ein Termin nötig ist, wie hoch die Mitgliedsgebühr ist und ob es besondere Schliessungen gibt, ist vor dem Besuch noch zu prüfen.","contacts[0].name":"Bibliothek","sources[0].label":"Kantonales Bibliotheksregister"}},
