"elki-alterswil":{"rev":"ea3c6229062e7ea93a8f45812425aa764a55e74c4655b92a934e1ed09afbfad1","strings":{"name":"ElKi Alterswil","age":"Ab 3 Jahren","schedule":"Freitag 10:00–11:00 laut Gruppenseite; Saison 2026/27 noch nicht bestätigt","price":"Preis nicht veröffentlicht","address":"Turnhalle Alterswil, 1715 Alterswil","research.findings[0].field":"Zeiten","research.findings[0].text":"Die Gruppenseite nennt Freitag 10:00–11:00, Turnhalle Alterswil, nicht 09:00. Kinder ab 3 Jahren sind mit Eltern oder Grosseltern eingeladen. In den geprüften Nachrichten wurde kein separates ElKi-Programm für 2026/27 gefunden.","research.remaining[0]":"Aktuelle Zeit, Kosten und die Möglichkeit eines Schnupperbesuchs klären; für Kinder unter 3 Jahren ist keine offizielle Zulassung angegeben.","sources[0].label":"Offizielle Quelle"}},
