"elki-giffers":{"rev":"fee9ca750479ecabf9dd3551e10d3e7c1c03f3db84ee2627c0b5f78373c50296","strings":{"name":"ElKi Giffers–Tentlingen","age":"Ab 2 Jahren","schedule":"Mi 09:30–10:45, Saison 2026/27; Beginn 09.09.2026","price":"CHF 80 / Jahr","address":"Sporthalle Giffers, 1735 Giffers","practical.indoor.text":"Sporthalle Giffers","practical.booking.text":"Anmeldung erforderlich; Startdatum 09.09.2026 ist veröffentlicht","practical.duration.text":"75 Minuten gemäss den veröffentlichten Zeiten","practical.leader.text":"Die Seite zur Saison 2026/27 nennt die Gruppenleitung","practical.warnings[0]":"Verfügbarkeit der Plätze, Schnupperbesuch und Ferienpausen prüfen","research.findings[0].field":"Format","research.findings[0].text":"Kinder ab 2 Jahren laufen, springen und probieren gemeinsam mit einer erwachsenen Person grosse und kleine Turngeräte aus. Anmeldung erforderlich. Saison 2026/27: Mittwoch 09:30–10:45, Beginn 9. September 2026, Sporthalle Giffers, CHF 80 pro Jahr.","research.remaining[0]":"Noch zu bestätigen: Verfügbarkeit der Plätze, Ferienpausen, Schnupperbesuch, Gruppengrösse und genauer Eingang. Die Diplome der Leitung sind nicht veröffentlicht.","sources[0].label":"Offizielle Quelle"}},
"elki-heitenried":{"rev":"2b2605bf8c063b22ca1109b9452965a3261672e4be65ef0936b2698782259e74","strings":{"name":"ElKi Heitenried · Turnen mit Elternteil","intro":"Das Plakat des TSV Heitenried für die Saison 2026/27 bestätigt: Start am 9. September, mittwochs 09:00–10:00 in der Turnhalle Heitenried, für Kinder ab etwa drei Jahren; es nennt auch eine Kontaktperson.","parentDetails":"Ein Elternteil oder eine andere nahestehende erwachsene Person nimmt gemeinsam mit dem Kind teil.","age":"Ungefähr ab 3 Jahren bis zum Kindergartenbeginn","schedule":"Mi 09:00–10:00, Saison 2026/27; Start 09.09.2026","price":"Preis nicht veröffentlicht","address":"Turnhalle Heitenried, 1714 Heitenried","notes[0]":"Für Kinder unter 3 Jahren muss die Aufnahme separat erfragt werden: Veröffentlicht ist «ab ca. 3 Jahren».","notes[1]":"Eine Turnstunde mit Liedern und spielerischen Übungen; die Sprache der Leitung ist nicht angegeben, Dialekt ist möglich.","practical.indoor.text":"Das Plakat des TSV Heitenried für die Saison 2026/27 bestätigt: Start am 9. September, mittwochs 09:00–10:00 in der Turnhalle Heitenried, für Kinder ab etwa drei Jahren; es nennt auch eine Kontaktperson.","practical.warnings[0]":"Verfügbarkeit von Plätzen, Mitgliederbeitrag, Schnupperbesuch und der genaue Eingang zur Halle sind nicht bestätigt.","research.findings[0].field":"Saison und Kontakt","research.findings[0].text":"Das Plakat 2026/27 bestätigt: Start am 9. September 2026, mittwochs 09:00–10:00 in der Turnhalle Heitenried, für Kinder ab etwa drei Jahren; es nennt auch eine Kontaktperson.","research.findings[1].field":"E-Mail","research.findings[1].text":"Die ElKi-Seite veröffentlicht die Adresse jugendsport@tsv-heitenried.ch für die Kontaktaufnahme mit der Leitung.","research.remaining[0]":"Aufnahme von Kindern unter 3 Jahren, Verfügbarkeit von Plätzen, Beitrag, Schnupperbesuch, Sprache und der genaue Eingang zur Halle müssen noch geklärt werden.","sources[0].label":"Verein: Format Jugendsport und E-Mail","sources[1].label":"Plakat 2026/27: Start, Zeiten, Halle, Alter und Telefon"}},
"elki-kerzers":{"rev":"cab880b220f2ff58aac1009311f7a037282714fdd94aee51b6dbdd068125d5b3","strings":{"name":"ElKi Kerzers","parentDetails":"Das Kind nimmt zusammen mit einer begleitenden erwachsenen Person teil.","age":"3–4 Jahre","schedule":"Die Anmeldung für 2026/27 wurde angekündigt; neue Zeiten noch nicht bestätigt","price":"CHF 100 pro Saison 2025/26; neue Gebühr noch nicht bestätigt","address":"Seelandhalle, Fräschelsgasse 11, 3210 Kerzers","notes[0]":"Die Seite des Vereins zeigt weiterhin den Kurs der letzten Saison, 28.10.2025–25.03.2026: Dienstag 09:00–10:00 oder 10:00–11:00, Mittwoch 10:00–11:00. Diese Zeiten sind für die neue Saison nicht bestätigt.","notes[1]":"Auf der Hauptseite des Vereins wurde am 7. September 2026 die offene Anmeldung für ElKi angekündigt. Die Detailseite zeigt weiterhin die vorherige Saison. Daten, freie Plätze und die neue Gebühr müssen noch bestätigt werden.","notes[2]":"Klettern, Balancieren, Rutschen, Springen und Schaukeln zusammen mit einer erwachsenen Person. Die Unterrichtssprache ist nicht veröffentlicht.","practical.warnings[0]":"Die Zeiten und die Gebühr beziehen sich auf die Saison 2025/26; fragen Sie nach den neuen Bedingungen.","research.findings[0].field":"Inhalt und Alter","research.findings[0].text":"Ein Kind im Alter von 3 bis 4 Jahren nimmt zusammen mit einer nahestehenden erwachsenen Person teil: Klettern, Balancieren, Rutschen, Springen, Schaukeln. Die Kursseite zeigt weiterhin 28.10.2025–25.03.2026 und CHF 100. Dies ist kein bestätigter Preis für die neue Saison.","research.findings[1].field":"Neue Anmeldung","research.findings[1].text":"Am 07.09.2026 gab der Verein bekannt, dass die Anmeldungen für ElKi offen sind. Dies bestätigt die Anmeldung, aber nicht die Zeiten, die Gebühr oder die freien Plätze für eine bestimmte Gruppe: Die Detailseite zeigt weiterhin die Saison 2025/26.","research.findings[2].field":"Adresse der Halle","research.findings[2].text":"Die Kursseite des TSV Kerzers nennt die Seelandhalle. Die Adresse der Halle ist Fräschelsgasse 11, 3210 Kerzers.","research.remaining[0]":"Die konkrete Gruppe, die Zeiten, der Preis und der Schnupperbesuch für 2026/27 müssen noch bestätigt werden. Die Zulassung von Kindern unter 3 Jahren ist nicht angegeben.","sources[0].label":"TSV Kerzers: ElKi, Alter und vorherige Saison","sources[1].label":"TSV Kerzers: Ankündigung der Anmeldung vom 07.09.2026","sources[2].label":"Neue Anmeldung","sources[3].label":"Adresse der Halle"}},
"elki-plaffeien":{"rev":"23efc92afa27710c05ed42b5028c58a5060804e8d300504f55874426f5109445","strings":{"name":"ElKi Plaffeien","intro":"ElKi (Eltern-Kind): Bewegung und Turnen für ein Kind zusammen mit einer erwachsenen Person.","age":"Ab 2,5 Jahren bis zum 1. Kindergarten","schedule":"Montag 17:00–18:00","price":"CHF 120; klären Sie den Zeitraum und was die Gebühr umfasst","address":"OS Plaffeien, Halle 1","notes[0]":"Prüfen Sie ab 4 Jahren die Einschulung in den 1. Kindergarten: Das ist die Grenze des Formats, keine strikte Altersgrenze.","notes[1]":"Ein Elternteil nimmt teil. Klären Sie den Schnupperbesuch, die Anzahl Kinder und was die Gebühr für Elternteil und Kind umfasst.","practical.indoor.text":"Termine in der OS-Turnhalle","practical.duration.text":"60 Minuten","practical.trial.text":"Der Verein lädt zu einem unverbindlichen Einführungsbesuch ein; vereinbaren Sie Teilnahme und Preis des ElKi-Schnupperbesuchs mit der Leitung","research.findings[0].field":"Schnupperbesuch","research.findings[0].text":"Der Verein lädt zu einem unverbindlichen Einführungsbesuch ohne Verpflichtung zum Beitritt ein. Für ElKi sind das Alter von 2,5 Jahren, eine erwachsene Begleitperson, Montag 17:00–18:00 und OS-Turnhalle 1 separat bestätigt, und die Gruppenleitung ist genannt. Vereinbaren Sie die Bedingungen des ersten Besuchs mit der Leitung.","research.findings[1].field":"Kosten","research.findings[1].text":"In der am 10. März 2025 beschlossenen Gebührentabelle kostet ElKi CHF 120, zweites Kind CHF 60. Der Zeitraum und die Frage, ob die erwachsene Person in dieser Gebühr enthalten ist, werden nicht direkt erklärt.","research.remaining[0]":"Die Kosten eines Schnupperbesuchs, die Gruppengrösse, der Gebührenzeitraum und die Qualifikation der Leitung sind nicht veröffentlicht.","contacts[0].name":"TV Plaffeien","sources[0].label":"Offizielle Quelle","sources[1].label":"Gebühren","sources[2].label":"Schnupperbesuch"}},
