"epicentre-pataugeoire-romont":{"rev":"dacffc0bf21b3a1aa7112d9ce2ca27f67dbad27bc15e4ed9a1af793c3ec6345a","strings":{"name":"Epicentre · Becken für Kleinkinder","intro":"Ein warmes, flaches Becken zum freien Schwimmen mit einem Elternteil.","parentDetails":"Das Kind bleibt im Wasser unter ständiger Aufsicht der erwachsenen Person.","age":"Flaches Becken für kleine Kinder; Eintritt frei bis 6 Jahre","schedule":"Während der Schulwochen Mo–Do 08–21, Fr 08–20:30, Sa 10–20, So 09–18; Ausnahmen auf der Website","price":"Erwachsene CHF 12; Kind unter 6 gratis; rückerstattbares Depot für den Pass CHF 5","address":"Route d'Arruffens 31, 1680 Romont","notes[0]":"Das flache Becken ist etwa 35 cm tief, mit Wasser von 30 °C und Wasserspielzeug. Es ist freies Schwimmen mit einem Elternteil, kein Eltern-Kind-Kurs.","notes[1]":"Laut Website ist das Kinderbecken während des ganzen Werktags verfügbar, aber die Zeiten ändern sich während der Schulferien und an Feiertagen.","notes[2]":"Für einen einzelnen Eintritt einer erwachsenen Person beträgt der Preis CHF 12 plus CHF 5 rückerstattbares Depot; mit einem Konto gelten separate zeitbasierte Tarife.","practical.indoor.text":"Hallenbad für Kleinkinder","practical.playArea.text":"Wasserspiel im flachen Becken","practical.costNote.text":"Erwachsene CHF 12, Kind unter 6 gratis; CHF 5 rückerstattbares Depot für den Pass","practical.warnings[0]":"Die Zeiten ändern sich während der Schulferien und an Feiertagen","practical.warnings[1]":"Dies ist freies Schwimmen, keine Lektion mit Kursleitung","research.findings[0].field":"Flaches Becken","research.findings[0].text":"Das Kleinkinderbecken, 35 cm tief, mit Wasser von 30 °C und Spielzeug, ist den ganzen Werktag verfügbar.","research.findings[1].field":"Eintritt für Kinder","research.findings[1].text":"Der Eintritt in den Wasserbereich ist für Kinder unter sechs Jahren frei.","research.findings[2].field":"Aufsicht","research.findings[2].text":"Die Regeln verlangen ständige Aufsicht durch eine erwachsene Person im Kinderbecken.","research.remaining[0]":"Prüfen Sie die Zeiten für das Datum des Besuchs und die Regeln zur Rückerstattung des Depots für den Pass.","contacts[0].name":"Epicentre","sources[0].label":"Flaches Becken, Zeiten, Preise und Adresse","sources[1].label":"Eintritt frei unter 6","sources[2].label":"Ständige Aufsicht im Kinderbecken"}},
