"fsg-chatel-parent-remaufens":{"rev":"b01274b9d62a5608364d7269c9bc2e38978e3e0df36ae8a5dc3350d1fa4977b9","strings":{"name":"FSG Châtel · Eltern-Kind-Turnen","intro":"Eltern-Kind-Turnen in Remaufens mit drei Schnupperterminen.","parentDetails":"Der Elternteil geht gemeinsam mit dem Kind die Posten und Übungen durch.","age":"Das Mindestalter ist auf der Seite zur Saison 2026/27 nicht angegeben","schedule":"Do 16:00–17:00, Saison 2026/27; Start 03.09.2026; Pausen in den Schulferien noch nicht bestätigt","price":"Preis nicht veröffentlicht","address":"Salle de gym de Remaufens, 1617 Remaufens","notes[0]":"Spielposten, Grundbewegungen und Übungen mit einem Elternteil; die Lektion beginnt mit einem Aufwärmen und endet mit einem Spiel oder einem Abzählreim.","notes[1]":"Der Anbieter schreibt, dass die definitive Anmeldung erst nach drei Schnupperterminen erfolgt, veröffentlicht aber weder das Alter noch die Gebühr noch die Verfügbarkeit der Plätze.","notes[2]":"Die Termine finden in Remaufens statt, nicht in der Halle Lussy in Châtel-St-Denis. Der genaue Eingang zur Halle sollte mit der Leitung geklärt werden.","practical.indoor.text":"Termin in der Turnhalle Remaufens","practical.duration.text":"Do 16:00–17:00, Saison 2026/27","practical.leader.text":"Gruppenleitung","practical.trial.text":"Drei Schnuppertermine vor der definitiven Anmeldung","practical.warnings[0]":"Mindestalter, Gebühr und Verfügbarkeit der Plätze sind nicht veröffentlicht","practical.warnings[1]":"Genauen Eingang zur Turnhalle prüfen","research.findings[0].field":"Gruppe 2026/27","research.findings[0].text":"Saison 2026/27: Das Eltern-Kind-Turnen findet in Remaufens donnerstags 16:00–17:00 statt, Start am 3. September 2026; definitive Anmeldung nach drei Schnupperterminen.","research.remaining[0]":"Mindestalter, Gebühr, Plätze und genauer Eingang zur Halle sind nicht veröffentlicht.","sources[0].label":"Saison, Tag, Zeit, Format, Leitung und drei Schnuppertermine"}},
