"fyfauter":{"rev":"f48c23adffe2c8b61acc22a1c7b5b7fe217e3b1d784a12ed3dc5259887d42cc5","strings":{"name":"Waldspielgruppe Fyfauter","age":"Alter noch nicht bestätigt","schedule":"Zeiten noch nicht bestätigt","price":"Preis nicht veröffentlicht","notes[0]":"Es liegen nur ältere Angaben vor. Die aktuelle Saison, der Ort, das Alter und ob ein Elternteil bleiben kann, sind nicht bestätigt.","practical.warnings[0]":"Es liegen nur ältere Angaben vor; ob die Gruppe noch stattfindet, ist nicht bestätigt","research.findings[0].field":"Unterscheidung zwischen Gruppen","research.findings[0].text":"Die Gemeinde hat bestätigt, dass sie die Spielgruppe Fyfauter in Plaffeien ab August 2025 übernimmt. Dies bestätigt nicht, dass die historische Waldspielgruppe in Schwarzsee weiterbesteht: Es kann nicht davon ausgegangen werden, dass Ort und Format übereinstimmen.","research.remaining[0]":"Ob die Waldspielgruppe in Schwarzsee selbst in Betrieb ist; Ort, Altersgruppe, Preis, Zeiten und ob ein Elternteil bleiben kann. Es kann nicht davon ausgegangen werden, dass die Gemeindegruppe in Plaffeien dieselbe Gruppe ist.","contacts[0].name":"Elternverein Plaffeien","sources[0].label":"Historisches Bulletin 2022","sources[1].label":"Unterscheidung zwischen Gruppen"}},
"garmiswil-restaurant":{"rev":"5c04c2bb543a9545da1fc2bc895c7f82fbee6767387608096b02a335635f23b4","strings":{"name":"Landgasthof Garmiswil · Restaurant mit Spielplatz","age":"Altersbeschränkungen des Spielplatzes prüfen.","schedule":"Mi–Sa 09:00–23:30; So 09:00–17:00; Mo–Di geschlossen","price":"Laut Speisekarte: grüner Salat CHF 11; halbes Poulet mit Beilage CHF 33","address":"Garmiswil 18, 3186 Düdingen","notes[0]":"Das Tourismusbüro bestätigt, dass das Restaurant, das eine Gartenterrasse hat, einen eigenen Kinderspielplatz hat. Dies ist eine Möglichkeit im Freien, kein bestätigter Spielraum im Innern.","notes[1]":"Die Website lädt Besucherinnen und Besucher auch ein, spontan auf einen Kaffee vorbeizukommen: Ein vollständiges Essen ist nicht das einzige angegebene Format. Der Preis für Kaffee und die Regeln für den Zugang zum Spielplatz bei einem solchen Besuch sind nicht veröffentlicht.","notes[2]":"Grüner Salat CHF 11; halbes Poulet mit Salat oder Pommes frites CHF 33. Das sind normale Gerichte der Speisekarte, kein Kindermenü und kein Eintrittsticket.","notes[3]":"Am Sonntag ist die Küche bis 15:00 geöffnet und das Restaurant bis 17:00. Prüfen Sie vor einem Besuch im Freien, ob der Spielplatz saisonal zugänglich ist.","notes[4]":"Prüfen Sie bei kleinen Kindern Geräte und Umzäunung. Der Elternteil bleibt für die Aufsicht verantwortlich; ein Betreuungsangebot ist nicht angegeben.","research.remaining[0]":"Geräte und Umzäunung für kleine Kinder.","contacts[0].name":"Landgasthof Garmiswil","sources[0].label":"Restaurant: Öffnungszeiten und Kontakte","sources[1].label":"Speisekarte mit Preisen","sources[2].label":"Besuchsformat, Café und Terrasse","sources[3].label":"Tourismusbüro: eigener Kinderspielplatz"}},
