"leflon-heron-trail":{"rev":"262c5591f2254815912b653334de9c2e0d4e0639b895e158be71cc678c96c3b9","strings":{"name":"La kotze dou éron · Waldspiele am Bach","intro":"Die Gemeinde bestätigt einen Weg in Pont mit einem Waldsofa, Spielen am Bach, Tischen und Naturmaterialien.","age":"Altersgrenzen sind nicht veröffentlicht","schedule":"Rundgang auf eigene Faust bei Tageslicht","price":"Preis nicht veröffentlicht","address":"Pont, 1699 Le Flon; genauen Start prüfen","notes[0]":"Verwenden Sie den Abschnitt «Accès» auf der Tourismusseite nicht: Er führt zu einem anderen Weg in Chapelle.","notes[1]":"Am Bach ist ständige Aufsicht nötig; Alter und Zugang mit Kinderwagen sind nicht angegeben.","practical.indoor.text":"Die Gemeinde bestätigt einen Weg in Pont mit einem Waldsofa, Spielen am Bach, Tischen und Naturmaterialien.","practical.warnings[0]":"Der genaue Einstiegspunkt und die Länge des örtlichen Wegteils sind nicht bestätigt. Die Tourismusseite verwechselt ihn mit der Wegbeschreibung nach Chapelle (Glâne).","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Die Gemeinde bestätigt einen Weg in Pont mit einem Waldsofa, Spielen am Bach, Tischen und Naturmaterialien.","research.remaining[0]":"Der genaue Einstiegspunkt und die Länge des örtlichen Wegteils sind nicht bestätigt. Die Tourismusseite verwechselt ihn mit der Wegbeschreibung nach Chapelle (Glâne).","contacts[0].name":"Commune Le Flon","sources[0].label":"Gemeinde: Weg in Pont und Kinderstationen","sources[1].label":"Tourismus: Beschreibung und falsche Wegbeschreibung"}},
"leset-villars":{"rev":"7ea92e8d0d817b3bd76fa8914407454fe3e959cac45ab87e6153724a9796830f","strings":{"name":"Le Set · Restaurant und Spielplatz bei der Terrasse","age":"Spielplatz für kleine Kinder; genaues Alter klären","schedule":"Mo 09:00–22:00; Di–Do 09:00–23:30; Fr–Sa 09:00–00:00; So geschlossen","price":"Kindergerichte CHF 10–14 auf der Frühlingskarte 2026; aktuelle Preise klären","address":"Avenue Jean-Paul II 11, 1752 Villars-sur-Glâne","notes[0]":"Der Anbieter bestätigt einen Spielplatz im Freien für die jüngsten Kinder bei der schattigen Terrasse auf zwei Ebenen. Es gibt auch Tischtennis und Pétanque; ein Spielraum im Innern ist nicht angegeben.","notes[1]":"Gäste sind auf der Terrasse ausdrücklich auch nur für ein Getränk willkommen, ohne volles Mittagessen. Das Restaurant hat kostenlose Parkplätze; die Anreise mit dem Bus Nr. 6 ist angegeben.","notes[2]":"Küche: Mo 11:30–14:00 und 18:00–21:30; Di–Do 11:30–14:00 und 18:00–22:00; Fr–Sa 11:30–14:30 und 18:00–22:00. Sonntag geschlossen.","notes[3]":"Die aktuelle Speisekartenseite bezieht sich auf die Frühlingskarte 2026: Kinderpasta CHF 10; Nuggets oder Roastbeef mit Beilage CHF 14. Ob diese Preise im Herbst gelten, ist nicht bestätigt.","notes[4]":"Der Anbieter beschreibt den Spielplatz als geschützt, aber die Art der Umzäunung und die Altersgrenzen sind nicht veröffentlicht. Fragen Sie bei kleinen Kindern nach den genauen Geräten, dem saisonalen Zugang und einer möglichen separaten Gebühr. Die Kinder bleiben bei ihrer erwachsenen Person.","research.remaining[0]":"Umzäunung und genaue Geräte.","contacts[0].name":"Le Set","sources[0].label":"Restaurant: Terrasse, Kinderspiel und Kontakte","sources[1].label":"Speisekartenseite","sources[2].label":"Frühlingskarte 2026: ein Anhaltspunkt, kein bestätigter Herbsttarif"}},
"library-courtepin":{"rev":"d9d2a907c207d48088cfb9abb1279bf05442fcbd3fa43c7b3f62ee235dfc9d02","strings":{"name":"Bibliothèque de Courtepin · Familienbesuch","parentDetails":"Das Kind besucht die Bibliothek mit einer erwachsenen Person; die Bibliothek bietet keine Aufsicht.","age":"Öffentliche Bibliothek; keine Altersgrenzen angegeben","schedule":"Donnerstag 17:00–19:00 für die Öffentlichkeit","price":"Preis nicht veröffentlicht","address":"Route de l’École 21, 1784 Courtepin","notes[0]":"Die Bibliothek dient hauptsächlich der Schule. Für Donnerstage sind separate öffentliche Öffnungszeiten veröffentlicht; die Schulzeiten sind nicht für Familienbesuche gedacht.","research.findings[0].field":"Öffentlicher Besuch","research.findings[0].text":"Das kantonale Verzeichnis trennt die Schulzeiten von den öffentlichen Öffnungszeiten: Donnerstag 17:00–19:00. Lesebereiche und Zugänglichkeit sind aufgeführt, aber es gibt keine Angaben zu einem Weg mit Kinderwagen.","research.remaining[0]":"Die Ferienöffnungszeiten für die Öffentlichkeit sind uneindeutig beschrieben; die Gebühr und das Angebot an Büchern für kleine Kinder sollten bestätigt werden.","contacts[0].name":"Bibliothèque de Courtepin","sources[0].label":"Kantonales Verzeichnis: öffentliche Öffnungszeiten und Adresse"}},
