"petites-rames-play":{"rev":"f23223fceba934a7623bc24d50684a372b5d4dd6adec8abe76721ed994eabae0","strings":{"name":"Petites-Rames · Spielplatz an der Sarine","intro":"Ein kleiner städtischer Spielplatz am Fluss mit Rutschbahn und Tischen.","age":"Altersgrenzen sind nicht veröffentlicht","schedule":"Offener Spielplatz; Öffnungszeiten sind nicht veröffentlicht","price":"Preis nicht veröffentlicht","address":"Petites-Rames, 1700 Fribourg","notes[0]":"Prüfen Sie vor Ort die Rutschbahn und die übrigen Geräte, ob sie für kleine Kinder geeignet sind; die Seilbahn ist kein Bereich für kleine Kinder.","notes[1]":"Der Spielplatz liegt in der Nähe des Flusses: Eine erwachsene Person muss in der Nähe bleiben.","practical.indoor.text":"Ein Spielplatz an der Sarine und der Saint-Jean-Brücke mit Rutschbahn, Seilbahn und Tischen.","practical.warnings[0]":"Das Mindestalter für die Seilbahn und die genauen Öffnungszeiten sind nicht veröffentlicht.","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Ein Spielplatz an der Sarine und der Saint-Jean-Brücke mit Rutschbahn, Seilbahn und Tischen.","research.remaining[0]":"Das Mindestalter für die Seilbahn und die genauen Öffnungszeiten sind nicht veröffentlicht.","contacts[0].name":"Fribourg Tourisme","sources[0].label":"Geräte und Lage"}},
"pferde-oberschrot":{"rev":"c8efe9d1364a5ae1f94b18c3ab7cc85c3ded6ecd9ee4afd6494c2765dc7517b0","strings":{"name":"Unterwegs mit Pferden","age":"7–18 Jahre","schedule":"23.09 und 21.10.2026; 24.03, 28.04 und 19.05.2027 · 14:00–17:00","price":"CHF 50 / Termin; Imbiss inbegriffen","address":"Lengisried 5, 1716 Oberschrot","notes[0]":"Pferdepflege, Bodenarbeit und geführte Ausritte. 4–8 Kinder.","notes[1]":"Die Anmeldung gilt für den ganzen Block: Die Anmeldefrist im Herbst (15.09.2026) ist bereits abgelaufen, die Anmeldefrist im Frühling ist der 24.02.2027. Klären Sie, ob freie Plätze vorhanden sind und ob ein späterer Einstieg möglich ist.","notes[2]":"Nicht geeignet für Kinder unter 7 Jahren. Die ständige Anwesenheit eines Elternteils und die Sprache sind nicht bestätigt.","research.findings[0].field":"Anmeldung","research.findings[0].text":"Die aktuelle Seite der Schule bestätigt das Programm für 7–18 Jahre, 4–8 Kinder und die Anmeldung direkt bei der Kursleitung. Die Anmeldefrist im Herbst, der 15. September, ist abgelaufen; die Anmeldefrist im Frühling ist der 24. Februar 2027. Die Versicherung ist Sache der teilnehmenden Person; die Anmeldung gilt für den ganzen Block. Die Hauptseite des Hofs enthält meist Berichte über vergangene Ausflüge, keine neuen Bedingungen für Kinder.","research.remaining[0]":"Ein späterer Einstieg, die Anwesenheit eines Elternteils und die veröffentlichte Qualifikation der konkreten Leitung sind nicht geklärt.","sources[0].label":"Programm Bergahorn 2026/27","sources[1].label":"Hof und Kontakt"}},
"pflueck-kerzers":{"rev":"1bd719580f4cf23f9e80ee271116dee8123d80183e8a5c8c778a99c10a3d83e4","strings":{"name":"Pflück dis Glück · Hof zum Selberpflücken","intro":"Ein Familienhof mit Hühnern und saisonalen Erzeugnissen zum Selberpflücken.","age":"Altersgrenzen sind nicht veröffentlicht","schedule":"Täglich 08:00–21:00 laut Kalender 2026/27; das Pflücken hängt von der Saison ab","price":"Bezahlt wird, was gepflückt wird, nach Gewicht oder Menge; Preise sind nicht angegeben","address":"Moosacker 1, 3210 Kerzers","notes[0]":"Erdbeeren werden von Mai bis Oktober aufgeführt, bezahlt wird nach Gewicht oder Menge; dies ist kein kostenloser Streichelzoo.","notes[1]":"Bei kleinen Kindern muss eine erwachsene Person beim Pflücken helfen und die Hofregeln befolgen.","practical.indoor.text":"Familien können saisonale Produkte pflücken, und Kindern wird angeboten, Hühner und Eier zu sehen.","practical.warnings[0]":"Was an einem bestimmten Datum zum Pflücken verfügbar ist, welche Kosten anfallen und welche Regeln für den Kontakt mit Tieren gelten, ist zu prüfen.","research.findings[0].field":"Angebot und Format","research.findings[0].text":"Familien können saisonale Produkte pflücken, und Kindern wird angeboten, Hühner und Eier zu sehen.","research.remaining[0]":"Was an einem bestimmten Datum zum Pflücken verfügbar ist, welche Kosten anfallen und welche Regeln für den Kontakt mit Tieren gelten, ist zu prüfen.","contacts[0].name":"Pflück dis Glück","sources[0].label":"Pflücken, Hühner, Öffnungszeiten und Bezahlung"}},
