"pitchounes-romont":{"rev":"8cfde6b552fbce8131bbe36da74fd496f5f14dd40457f8d6d5ff0cf9cfd72343","strings":{"name":"La Maison des Pitchounes · freies Spiel","intro":"Ruhiges freies Spiel mit einer erwachsenen Person und den Fachpersonen, die die Familien empfangen.","parentDetails":"Das Kind kommt mit einem Elternteil oder einer anderen nahen erwachsenen Person; eine oder zwei Fachpersonen empfangen die Familien.","age":"Ab Geburt bis zum Beginn der 1H (ca. 0–4 Jahre)","schedule":"Mo 14:00–17:30; Mi 09:00–11:30","price":"Gratis","address":"Rue du Château 126, 1680 Romont FR","notes[0]":"Keine Anmeldung; Sie können auch nur für einen Teil der Zeit kommen. Dies ist ein Ort für freies Spiel, keine Kita.","notes[1]":"Das Erdgeschoss ist als zugänglich für einen Kinderwagen aufgeführt. Während der Schulferien kündigt der Anbieter gesonderte Termine am Mittwoch an.","notes[2]":"Die Seite verwendet sowohl Rue als auch Route du Château; der Kontaktblock unten nennt Rue du Château 126. Prüfen Sie für die Navigation die Markierung auf der Karte.","practical.indoor.text":"Freies Spiel drinnen","practical.access.text":"Der Anbieter gibt an, dass das Erdgeschoss mit einem Kinderwagen zugänglich ist","practical.booking.text":"Keine Anmeldung","practical.observe.text":"Sie können zuerst einfach in der Nähe des Kindes bleiben","practical.commitment.text":"Freier Eintritt","practical.leave.text":"Freie Aufenthaltsdauer innerhalb der Empfangszeit","research.findings[0].field":"Erster Besuch","research.findings[0].text":"Ein Ort für Kinder von der Geburt bis zur 1H: keine Anmeldung, kostenlos und zusammen mit einer erwachsenen Person; eine oder zwei Fachpersonen pro Schicht.","research.remaining[0]":"Klären Sie die Sprache beim Empfang und Ausnahmen in den Ferien; die Website ist uneinheitlich und nennt teils Rue, teils Route du Château.","contacts[0].name":"La Maison des Pitchounes","sources[0].label":"Format, Alter, Zeiten, freier Eintritt und Adresse"}},
"plage-chevroux":{"rev":"9d9d5448e1755c83b7057f6caa620ed76dbd975fe0f163a06b1e1473c682e928","strings":{"name":"Plage de Chevroux · ausserhalb des Kantons","intro":"Sandstrand mit Schatten und Picknickplatz.","parentDetails":"Familienbesuch auf eigene Faust; ein Kind am Wasser nur mit einer erwachsenen Person.","age":"Familienstrand; kein Mindestalter angegeben","schedule":"Kanton Vaud; nicht Teil der Auswahl des Kantons Freiburg","price":"Preis nicht veröffentlicht","address":"Avenue du Port 10, 1545 Chevroux","notes[0]":"Sand, Schatten, WC, Dusche, Picknickplatz und fester Grill. Die Quelle gibt nicht an, dass es einen Spielplatz gibt.","notes[1]":"Parkplätze beim Hafen sind etwa zwei Minuten zu Fuss entfernt, CHF 1/Stunde. Der Eintrittspreis ist nicht angegeben.","notes[2]":"Hunde sind am Strand nicht erlaubt; in der Nähe gibt es ein Restaurant.","notes[3]":"Die Gemeinde Chevroux gehört zum Kanton Vaud, deshalb wurde die Karte ins Archiv des kantonalen Katalogs verschoben.","practical.indoor.text":"Strand unter freiem Himmel","practical.toilet.text":"WC und Dusche vorhanden","practical.parking.text":"Parkplätze CHF 1/Stunde, etwa zwei Minuten zu Fuss","practical.warnings[0]":"Ein Kinderspielplatz ist in der Quelle nicht angegeben","research.findings[0].field":"Kantonsgrenze","research.findings[0].text":"Chevroux ist in der offiziellen Gemeindeliste des Kantons Vaud (OFS 5813) aufgeführt; es ist kein Ort im Kanton Freiburg.","research.remaining[0]":"Die Karte bleibt im Archiv; nicht unter den aktiven Orten des Kantons Freiburg anzeigen.","contacts[0].name":"Commune de Chevroux","sources[0].label":"Fläche, Ausstattung, Kontakt und Parkplätze","sources[1].label":"Zusätzliche Prüfung: Kantonsgrenze"}},
"plage-cheyres":{"rev":"842db867b1e0c563694d1e2eb3bab281da84e4f33054732851feddc20e8617fc","strings":{"name":"Plage de Cheyres · Ort am See","intro":"Schattiger Strand mit Spielplatz und Picknickbereich.","parentDetails":"Eine erwachsene Person bleibt jederzeit mit dem Kind am Wasser.","age":"Familienstrand; der Altersbereich der Geräte ist nicht angegeben","schedule":"Öffentlicher Strand; die Verfügbarkeit der Angebote hängt von der Saison ab","price":"Preis nicht veröffentlicht","address":"Route du Port, 1468 Cheyres-Châbles","notes[0]":"Sand und schattige Wiese, Spielplatz, WC, Dusche, Picknickbereich und Restaurant.","notes[1]":"Der Bahnhof Cheyres ist zu Fuss erreichbar. Der kostenpflichtige Parkplatz unterhalb des Bahnhofs, etwa acht Minuten zu Fuss vom Strand, ist von Mai bis September geöffnet.","notes[2]":"Der Eintrittspreis ist nicht veröffentlicht. Hunde sind von Mai bis September nicht erlaubt. Im Winter sind sie an der Leine erlaubt, aber nicht im Wasser.","practical.indoor.text":"Strand im Freien","practical.playArea.text":"Spielplatz","practical.toilet.text":"WC und Dusche","practical.parking.text":"Kostenpflichtige Parkplätze, etwa acht Minuten zu Fuss","research.findings[0].field":"Familieneinrichtungen","research.findings[0].text":"Es gibt einen Spielplatz, Sand, Schatten, WC und Dusche. Parkplätze sind kostenpflichtig und etwa acht Minuten zu Fuss entfernt.","research.remaining[0]":"Der Eintrittspreis und die Zeiten der saisonalen Angebote sind nicht veröffentlicht.","contacts[0].name":"Commune de Cheyres-Châbles","sources[0].label":"Spielbereich, Schatten, Angebote, Zugang und saisonale Regeln"}},
"plage-portalban":{"rev":"ca3d387d3c259ee1702cc567b8727e6afb8b3bdaedc78ca506d8f5487abc46c1","strings":{"name":"Plage de Portalban · Ort am Wasser","intro":"Ein Strand mit Spielplatz, Picknickbereich und gebührenpflichtigen Parkplätzen.","parentDetails":"Eine erwachsene Person bleibt am Wasser und auf dem Spielplatz beim Kind.","age":"Familienstrand; für welches Alter die Spielgeräte gedacht sind, ist nicht angegeben","schedule":"Strandbereich; Saison für die Angebote prüfen","price":"Preis nicht veröffentlicht","address":"Route du Port, 1568 Delley-Portalban","notes[0]":"Sand und Rasen, Spielplatz, WC, Dusche, Picknickbereich und Imbissstand; wenig Schatten.","notes[1]":"Parkplätze: CHF 1/Stunde unter der Woche, CHF 1.50/Stunde am Wochenende. Als Tagestarife sind CHF 8 und CHF 12 angegeben; prüfen Sie, welcher gilt. Der Eintrittspreis für den Strand ist nicht veröffentlicht.","notes[2]":"Hunde und eigene Grills sind nicht erlaubt. Imbissstand und Mietangebote sind saisonal.","practical.indoor.text":"Sandstrand im Freien","practical.playArea.text":"Es gibt einen Spielplatz","practical.toilet.text":"WC und Dusche am Strand","practical.parking.text":"CHF 1/Stunde unter der Woche, CHF 1.50/Stunde am Wochenende","research.findings[0].field":"Am Wasser","research.findings[0].text":"Der Strand hat einen Spielplatz, WC, Dusche, Picknickbereich und Imbissstand; die Parkplätze sind gebührenpflichtig und am Wochenende teurer.","research.remaining[0]":"Der Eintrittspreis und die Öffnungszeiten des saisonalen Imbissstands sind nicht angegeben.","contacts[0].name":"Commune de Delley-Portalban","sources[0].label":"Gelände, Einrichtungen, Parkplätze und Adresse"}},
