"playgrounds-marly":{"rev":"79ac5a2ceec62df05b1d00c1be87f90941b21947bc00b515cbfb881792233f85","strings":{"name":"Playgrounds Marly Grand-Pré","age":"0–6 Jahre","schedule":"Die Saison 2025/26 ist beendet; neue Daten für 2026/27 sind nicht veröffentlicht","price":"Eintritt frei","address":"Rte des Écoles 34, petite halle, Marly","notes[0]":"Die allgemeine Seite zeigt keine kommenden Termine für Marly, und die Seite von Marly listet nur Daten bis März 2026. Gehen Sie nicht ohne Bestätigung hin.","notes[1]":"Eine offene Halle, keine kleine ruhige Gruppe.","practical.warnings[0]":"Die Saison ist beendet; neue Daten sind nicht veröffentlicht","research.findings[0].field":"Saison","research.findings[0].text":"Die Seite von Marly listet weiterhin nur Daten bis zum 29. März 2026, und das allgemeine Programm zeigt keine kommenden Termine für Marly. Im Winter gab es Öffnungen von 90 und von 120 Minuten, die Dauer der Termine war also unterschiedlich. Die Saison 2026/27 ist nicht bestätigt.","research.remaining[0]":"Neue Daten und Dauer, Zulassung kleiner Kinder, Teilnahme erwachsener Personen.","sources[0].label":"Offizielle Quelle"}},
"pony-entdecken":{"rev":"b6c013a7f3c439e82cde66d774d430ee77d8f60c7b0b31a71f371bf6822513eb","strings":{"name":"Pony entdecken · Tierhappy","parentDetails":"Eltern dürfen bleiben; eine gemeinsame Lektion für Elternteil und Kind ist nicht ausgeschrieben.","age":"4–6 Jahre","schedule":"24.09, 01.10 und 08.10.2026 · 14:00–16:00","price":"CHF 25 / Termin; Anmeldung für einen Block von 3 Terminen","address":"Ober Tschüplere 90, 1716 Oberschrot","notes[0]":"Ponys kennenlernen, putzen, füttern, führen und Spiele. Reiten wird in der Beschreibung der jüngeren Gruppe nicht versprochen.","notes[1]":"2–4 Kinder; ein kleiner Imbiss ist inbegriffen. Drei Termine zu CHF 25: berechnete Blocksumme CHF 75.","notes[2]":"Die Gruppen stehen auch Kindern offen, die nicht die Schule Bergahorn besuchen. Eine Teilnahme unter 4 Jahren kann besprochen werden, ist aber nicht bestätigt.","notes[3]":"Vereinbaren Sie die Sprache des Termins. Wettergerechte Kleidung und passendes Schuhwerk sind nötig.","research.findings[0].field":"Kursleitung","research.findings[0].text":"Die Kursleitung nennt einen Bachelor in Sozialpädagogik (Bachelor en éducation sociale, 2014), Arbeit mit Menschen mit geistiger Beeinträchtigung und eine Ausbildung in tiergestützter Intervention (intervention assistée par l’animal) bei Ani-motion, Niederbipp, in den Jahren 2017–2019. Bis 2026 arbeitete sie mit Menschen mit psychischen oder sozialen Schwierigkeiten. Dies ist die eigene Biografie der Kursleitung, keine unabhängige Bestätigung und kein Beleg für Erfahrung mit kleinen Kindern.","research.remaining[0]":"Für Kinder unter 4 Jahren ist eine Teilnahme nur nach gesonderter Absprache möglich. Das Programm ist offiziell für das Alter 4–6 gedacht. Klären Sie die Sprache und ob ein Platz frei ist.","contacts[0].name":"Bergahorn: Anmeldung für Pony-Termine","sources[0].label":"Bergahorn-Programm 2026/27","sources[1].label":"Tierhappy · Anbieter","sources[2].label":"Kursleitung"}},
"pony-spass":{"rev":"9a7bf5378426c0a8d414332219912e439293d99cafa44d7ecaacc8ce4acfd477","strings":{"name":"Pony Spass · Tierhappy","parentDetails":"Eltern dürfen bleiben; eine gemeinsame Lektion für Elternteil und Kind ist nicht angegeben.","age":"6–9 Jahre","schedule":"16. Oktober 2026 · 13:30–16:00","price":"CHF 30 / Termin; Imbiss inbegriffen","address":"Ober Tschüplere 90, 1716 Oberschrot","notes[0]":"Ponypflege, Füttern, Reiten oder Führen des Ponys, Spiele. Gruppe mit 2–4 Kindern.","notes[1]":"Dies ist ein Programm für ältere Kinder, keine Option für Kinder unter 6 Jahren. Frühlingstermine sind noch nicht aufgeführt.","notes[2]":"Sprache noch zu vereinbaren; wettergerechte Kleidung und passendes Schuhwerk.","research.findings[0].field":"Kursleitung und Format","research.findings[0].text":"Die aktuelle Bergahorn-Seite bestätigt die Kursleitung, die Altersgruppe 6–9, 2–4 Kinder, die Erlaubnis für Eltern zu bleiben und einen Termin am 16. Oktober 2026. Für Kinder unter 6 Jahren ist dies keine bestätigte Option.","research.remaining[0]":"Sprache, freie Plätze und Frühlingstermine. Eine ausführliche Biografie der Kursleitung ist bei Tierhappy verfügbar.","contacts[0].name":"Bergahorn: Anmeldung für Ponytermine","sources[0].label":"Bergahorn-Programm 2026/27","sources[1].label":"Tierhappy · Anbieter"}},
