"santiklous":{"rev":"df59bb387f3d0761bd23e3b7b4a01600f51184c06013f1c2f600a6fce3c7cc72","strings":{"name":"Santiklousumzug","age":"Alter noch nicht bestätigt","schedule":"6. Dezember 2026 · Umzug trifft ungefähr um 17:30 ein","price":"Preis nicht veröffentlicht","address":"Dorfplatz, 1716 Plaffeien","notes[0]":"Die Sprache der gastgebenden Person oder des Angebots ist nicht bestätigt.","notes[1]":"Alter und Bedingungen noch nicht bestätigt; ein Umzug mit Glocken ist keine ruhige Aktivität.","research.findings[0].field":"Programm","research.findings[0].text":"6. Dezember 2026, Dorfplatz: Der Umzug trifft ungefähr um 17:30 ein. Danach folgt ein Auftritt auf dem Balkon des Hirschen, ein Empfang für die Kinder und Lebkuchen. Trychler und Gysler nehmen teil: Es ist ein lautes Strassenfest. Eine Seite nennt für den Kiosk zwei verschiedene Öffnungszeiten: 16:30 und ungefähr 16:45.","research.remaining[0]":"Die Dauer, mögliche Überschneidungen mit anderen Anlässen und ein guter Platz zum Zuschauen mit kleinen Kindern sind noch nicht bestätigt. Ein Eintrittspreis ist nicht angegeben.","contacts[0].name":"Elternverein Plaffeien","sources[0].label":"Offizielle Quelle"}},
"sarrazin-lossy-play":{"rev":"5df5eff56d031e71c4bf5649c3783356c6effc27bb9df485cbef4e6660fd2b65","strings":{"name":"Le Sarrazin · Mittagessen mit Kinderspielbereich","intro":"Die Tourismusseite beschreibt ausdrücklich einen Spielbereich innen und aussen beim Familienrestaurant in Lossy.","age":"Altersgrenzen sind nicht veröffentlicht","schedule":"Prüfen Sie die Öffnungszeiten des Restaurants vor dem Ausflug","price":"Preis nicht veröffentlicht","address":"Route des Sarrazins 115, 1782 Lossy","notes[0]":"Eine Aufsicht durch das Personal ist nicht angegeben; eine erwachsene Person ist für das Kind verantwortlich, auch wenn es einen separaten Spielraum gibt.","notes[1]":"Ob der Aussenbereich in der jeweiligen Jahreszeit genutzt werden kann, hängt vom Wetter ab; prüfen Sie die Preise der Gerichte auf der aktuellen Speisekarte.","practical.indoor.text":"Die Tourismusseite beschreibt ausdrücklich einen Spielbereich innen und aussen beim Familienrestaurant in Lossy.","practical.warnings[0]":"Das Altersspektrum der Geräte, ob der Spielbereich von den Tischen aus sichtbar ist, das Kindermenü und die Öffnungszeiten sind nicht veröffentlicht.","research.findings[0].field":"Verfügbarkeit und Format","research.findings[0].text":"Die Tourismusseite beschreibt ausdrücklich einen Spielbereich innen und aussen beim Familienrestaurant in Lossy.","research.remaining[0]":"Das Altersspektrum der Geräte, ob der Spielbereich von den Tischen aus sichtbar ist, das Kindermenü und die Öffnungszeiten sind nicht veröffentlicht.","contacts[0].name":"Le Sarrazin","sources[0].label":"Tourismus: Räumlichkeiten und Aussenspielbereich, Adresse"}},
"sarrazin-lossy":{"rev":"762178eea58d091b98b36346db9a5a55aa7ad0eaff06c69b4367afc0ab9b1a1e","strings":{"name":"Le Sarrazin · Spiele drinnen und draussen","age":"Alter für die Spielbereiche noch nicht bestätigt","schedule":"Mi–Sa 10:00–23:00; So und Feiertage 10:00–17:00; Mo–Di geschlossen","price":"Kindergerichte CHF 10–16; für Kinder bis 4 Jahre ist ein leerer Teller gratis","address":"Route des Sarrazins 115, 1782 Lossy","notes[0]":"Das Tourismusbüro bestätigt Spielbereiche drinnen und draussen. Das Spielangebot, die Grösse und ein separater Bereich für kleine Kinder sind nicht beschrieben.","notes[1]":"Kinderkarte für Kinder bis 10 Jahre: Gemüse CHF 10, Pasta mit Tomatensauce CHF 12, Mini-Burger oder Nuggets mit Beilage CHF 15, Mini-Steak mit Beilage CHF 16.","notes[2]":"Kinder unter 4 Jahren erhalten gratis einen leeren Teller, um das Essen der Eltern zu teilen. Das ist kein Gratis-Kindergericht und keine Bestätigung für freien Eintritt in den Spielbereich. Das Tagesgericht für Erwachsene auf der Startseite kostet ab CHF 21.","notes[3]":"Die Küche ist 11:30–13:30 und 18:30–21:00 geöffnet; sonntags und an Feiertagen schliesst das Restaurant um 17:00, und an diesen Tagen gibt es keinen Abendservice. Die Zahl der Gäste pro Service ist begrenzt.","notes[4]":"Fragen Sie nach Altersbeschränkungen für die Geräte, nach dem Zugang zu den Spielen und danach, ob eine Bestellung nötig ist. Eine erwachsene Person bleibt beim Kind; eine Aufsicht durch das Personal ist nicht angegeben.","research.remaining[0]":"Die genauen Geräte, die Sicht auf den Bereich und ein separater Bereich für kleine Kinder.","contacts[0].name":"Le Sarrazin","sources[0].label":"Restaurant: Speisekarte, Öffnungszeiten und Kontakte","sources[1].label":"Kindergerichte, Teller für Kinder bis 4 Jahre und Küchenzeiten","sources[2].label":"Tourismusbüro: Spiele drinnen und draussen"}},
